import NoteContext from "./noteContext";
import { useState, useEffect } from "react";

const NoteState = (props) => {
  const host = "http://localhost:5000";
  const notesInitial = [];
  const [notes, setNotes] = useState(notesInitial);
  const [isLoading, setIsLoading] = useState(false);

  // Helper function to get auth token
  const getAuthToken = () => {
    return localStorage.getItem('token');
  };

  // Helper function to check if user is authenticated
  const isAuthenticated = () => {
    const token = getAuthToken();
    return !!token;
  };

  // Get all Notes
  const getNotes = async () => {
    if (!isAuthenticated()) {
      console.log("User not authenticated, skipping getNotes");
      setNotes([]);
      return;
    }

    setIsLoading(true);
    try {
      const token = getAuthToken();
      console.log("Fetching notes with token:", token ? "present" : "missing");
      
      const response = await fetch(`${host}/api/notes/fetchallnotes`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          "auth-token": token
        }
      });

      console.log("Response status:", response.status);

      if (!response.ok) {
        if (response.status === 401) {
          console.log("Unauthorized - clearing token");
          localStorage.removeItem('token');
          setNotes([]);
          return;
        }
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const json = await response.json();
      console.log("Fetched notes response:", json);
      console.log("Type of response:", typeof json);
      console.log("Is array:", Array.isArray(json));
      
      // Ensure we always set an array
      if (Array.isArray(json)) {
        console.log("Setting notes array with length:", json.length);
        setNotes(json);
      } else if (json && json.notes && Array.isArray(json.notes)) {
        console.log("Setting notes from json.notes with length:", json.notes.length);
        setNotes(json.notes);
      } else {
        console.error("API returned unexpected format:", json);
        setNotes([]);
      }
    } catch (error) {
      console.error("Error fetching notes:", error);
      setNotes([]);
    } finally {
      setIsLoading(false);
    }
  };

  // Auto-fetch notes when authentication status changes
  useEffect(() => {
    console.log("NoteState useEffect - isAuthenticated:", props.isAuthenticated);
    if (props.isAuthenticated) {
      console.log("User is authenticated, fetching notes...");
      getNotes();
    } else {
      console.log("User not authenticated, clearing notes");
      setNotes([]);
    }
  }, [props.isAuthenticated]);

  // Add a Note
  const addNote = async (title, description, tag) => {
    if (!isAuthenticated()) {
      console.log("User not authenticated, cannot add note");
      return false;
    }

    try {
      const token = getAuthToken();
      const response = await fetch(`${host}/api/notes/addnote`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          "auth-token": token
        },
        body: JSON.stringify({ title, description, tag })
      });

      if (!response.ok) {
        if (response.status === 401) {
          localStorage.removeItem('token');
          return false;
        }
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      console.log("Add note API Response:", result);
      
      // Handle the response structure { success: true, note: {...} }
      if (result.success && result.note && result.note._id) {
        console.log("Adding note to state:", result.note);
        setNotes(prevNotes => {
          // Ensure prevNotes is always an array
          const currentNotes = Array.isArray(prevNotes) ? prevNotes : [];
          return [result.note, ...currentNotes];
        });
        return true;
      } 
      // Fallback: if the response is just the note object directly
      else if (result._id) {
        console.log("Adding note to state (direct):", result);
        setNotes(prevNotes => {
          // Ensure prevNotes is always an array
          const currentNotes = Array.isArray(prevNotes) ? prevNotes : [];
          return [result, ...currentNotes];
        });
        return true;
      } 
      else {
        console.error("Invalid note response structure:", result);
        return false;
      }
    } catch (error) {
      console.error("Error adding note:", error);
      return false;
    }
  };

  // Delete a Note
  const deleteNote = async (id) => {
    if (!isAuthenticated()) {
      console.log("User not authenticated, cannot delete note");
      return false;
    }

    try {
      const token = getAuthToken();
      const response = await fetch(`${host}/api/notes/deletenote/${id}`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
          "auth-token": token
        }
      });

      if (!response.ok) {
        if (response.status === 401) {
          localStorage.removeItem('token');
          return false;
        }
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      console.log("Deleting note with id:", id);
      setNotes(prevNotes => {
        const currentNotes = Array.isArray(prevNotes) ? prevNotes : [];
        return currentNotes.filter((note) => note._id !== id);
      });
      return true;
    } catch (error) {
      console.error("Error deleting note:", error);
      return false;
    }
  };

  // Edit a Note
  const editNote = async (id, title, description, tag) => {
    if (!isAuthenticated()) {
      console.log("User not authenticated, cannot edit note");
      return false;
    }

    try {
      const token = getAuthToken();
      const response = await fetch(`${host}/api/notes/updatenote/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          "auth-token": token
        },
        body: JSON.stringify({ title, description, tag })
      });

      if (!response.ok) {
        if (response.status === 401) {
          localStorage.removeItem('token');
          return false;
        }
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const json = await response.json();
      console.log("Editing note:", json);

      // Use functional state update for better reliability
      setNotes(prevNotes => {
        // Ensure prevNotes is always an array
        const currentNotes = Array.isArray(prevNotes) ? prevNotes : [];
        return currentNotes.map(note => {
          if (note._id === id) {
            return {
              ...note,
              title: title,
              description: description,
              tag: tag
            };
          }
          return note;
        });
      });
      return true;
    } catch (error) {
      console.error("Error editing note:", error);
      return false;
    }
  };

  return (
    <NoteContext.Provider value={{ 
      notes, 
      addNote, 
      deleteNote, 
      editNote, 
      getNotes,
      isLoading,
      isAuthenticated: props.isAuthenticated
    }}>
      {props.children}
    </NoteContext.Provider>
  );
};

export default NoteState;
